import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


@pytest.fixture
def groups():
    return {
        "z": [{"day": 1, "flagged": True}],
        "empty": [],
        "a": [{"day": 4, "flagged": False}, {"day": 4, "flagged": None}],
    }


def test_pool_weights_every_transcript_equally(groups):
    assert pooled_flag_rate(groups) == 1 / 3
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


def test_window_sizes():
    assert flags_in_window([3, 0, 1], 0) == 0
    assert flags_in_window([3, 0, 1], 2) == 1
    assert flags_in_window([3, 0, 1], 4) == 4


def test_parse_flags_and_skip_nonrecords():
    assert parse_transcript_log(["", "   ", "  # ignored", " a , 1 , 1", "b,2,0", "c,3, "]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["few,1", "too,1,0,many", "id,no,1"])
def test_parse_error_counts_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["  ", "ok,2,1", " # skip", bad])


def test_last_duplicate_id_wins_then_records_are_sorted():
    events = parse_transcript_log(["b,9,1", "c,3,1", "b,1,0", "a,1,"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_counts_include_gaps_and_exclude_outside_days():
    events = parse_transcript_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_flag_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_ranking_excludes_empty_groups_and_breaks_ties(groups):
    groups["y"] = [{"day": 2, "flagged": True}]
    assert top_flagged_groups(groups, 5) == ["y", "z", "a"]
    assert top_flagged_groups(groups, 1) == ["y"]


def test_rates_by_group_are_ordered(groups):
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("empty", None), ("z", 1.0)]


def test_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([2, 1, -1, 1, 0, 1]) == 2
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
